-- Paket ABT u5-ahli-waris (agen U5, 20 Okt 2026): variabel 4500-4599 untuk penetapan ahli waris / P3HP, blangko derry_briantono.
-- Dijalankan: mysql --default-character-set=latin1 aps_badilag < abt-u5-PASANG.sql
-- Isi teks berupa literal heksadesimal (bita ASCII apa adanya). JANGAN disunting di editor.

SET NAMES latin1;
-- PRASYARAT: berhenti dengan galat "Subquery returns more than 1 row" bila jatah 4500-4599 sudah terpakai. Tidak ada yang ditulis.
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE no_var BETWEEN 4500 AND 4599) = 0, 'PRASYARAT COCOK - memasang', (SELECT 'PRASYARAT GAGAL' UNION SELECT 'BERHENTI')) AS prasyarat;

START TRANSACTION;
